"""Complete 36 original mechanical ventilation/liberation questions."""
from create_critical_ards_obstruction import rows,q,PV,AR,ES,NM,ref
from qbank_authoring import finalize
SB=ref('AARC spontaneous breathing trial guideline: 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11285503/')
LI=ref('ATS/CHEST liberation guideline: rehabilitation and cuff-leak testing','https://www.thoracic.org/statements/resources/cc/weaning-rehab-protocols-CLT.pdf')
NI=ref('ERS/ATS acute noninvasive ventilation guideline','https://www.thoracic.org/statements/resources/cc/niv-guidelines.pdf')
NS=ref('ATS adult acute noninvasive respiratory support guideline: 2026','https://academic.oup.com/ajrccm/article/212/9/2135/8721554')

q('What is the role of RSBI in deciding readiness for a spontaneous breathing trial under the 2024 AARC guideline?', 'It is not required as a mandatory screening gate before an otherwise appropriate SBT',[
 ('It must be below 105 before any patient can ever undergo an SBT','The guideline does not require this universal gate.'),('It directly assesses airway protection and secretion clearance','It measures a breathing pattern, not those extubation functions.'),('It can replace clinical assessment of stability and oxygenation','Readiness requires a broader assessment.')],
 'Do not let a traditional index delay an appropriate trial','**RSBI is respiratory frequency divided by tidal volume in liters.**',['It can provide supporting information but is not mandatory to decide SBT readiness.','The underlying cause, oxygenation, hemodynamics and ability to initiate breathing matter.'], '**Use a standardized daily readiness assessment.**',['Passing an SBT is not identical to being ready for tube removal.','Assess airway competence and the overall extubation plan separately.'],[['RSBI','Breathing-pattern index'],['SBT readiness','Broader stability assessment'],['Extubation','Also needs airway assessment']],[SB])

q('Which SBT method is acceptable under current AARC guidance?', 'An SBT with or without low-level pressure support, using a standardized local approach',[
 ('Only a T-piece, because any support invalidates every trial','Both approaches can be used.'),('Only pressure support above 20 cm H2O','That is substantial support and not the intended low-support SBT approach.'),('A mandatory maximal exercise test before every SBT','This is not the guideline requirement.')],
 'Test spontaneous capacity without turning one method into a universal rule','**AARC accepts SBTs with or without pressure support.**',['The chosen method and support level affect the load imposed.','Use consistent interpretation and do not mistake high assistance for an unassisted capacity test.'], '**Monitor breathing, gas exchange, comfort and circulation.**',['Stop a failing trial safely and investigate reversible causes.','Repeat after correction rather than prolonging an unsuccessful test.'],[['T-piece','One accepted method'],['Low-level PS','Another accepted method'],['Interpretation','Depends on the trial conditions']],[SB])

q('Should FiO2 routinely be increased just before an SBT to make the oxygen saturation look better?', 'No; avoid increasing FiO2 during the trial as a routine strategy',[
 ('Yes, to 1.0 for every patient regardless of baseline','This can hide oxygenation failure under the intended conditions.'),('Yes, because oxygenation is irrelevant during an SBT','Gas-exchange adequacy is part of the assessment.'),('Yes, until all respiratory distress disappears without assessing the cause','Supplemental oxygen can conceal one sign without correcting the mechanism.')],
 'Do not mask failure by changing the test conditions','**AARC suggests not increasing FiO2 during SBTs.**',['A patient who needs escalation for hypoxemia needs clinical care, not a falsely successful trial.','Interpret the result with the baseline support and clinical state.'], '**Use a standardized, safe trial.**',['Provide rescue support if necessary and reassess why failure occurred.','Do not sacrifice safety to complete a protocol.'],[['Stable test conditions','Improve interpretation'],['Hypoxemia','Needs assessment/rescue'],['Artificial FiO2 increase','Can mask inadequate readiness']],[SB])

q('A patient passes an SBT but has a very weak cough, copious secretions and impaired airway protection. What is the best interpretation?', 'Successful spontaneous breathing does not by itself establish safe extubation',[
 ('The SBT guarantees successful tube removal','Airway competence and secretion management are separate issues.'),('RSBI alone can override the airway findings','A breathing index does not establish airway protection.'),('A normal chest radiograph guarantees no aspiration risk','Radiography cannot certify bulbar competence.')],
 'Weaning from support and removing the airway are different decisions','**An SBT assesses ventilatory capacity under the test conditions.**',['Extubation also depends on cough, secretions, mental status and upper-airway risk.','The patient’s underlying disease and expected postextubation support matter.'], '**Investigate and improve reversible barriers.**',['Balance the harm of premature removal against unnecessary intubation.','Use a planned airway and rescue strategy.'],[['SBT','Ventilatory capacity'],['Cough/secretions','Airway competence'],['Extubation plan','Integrates both']],[LI,SB],style='clinical_scenario')

q('In whom is a cuff-leak test particularly appropriate before planned extubation?', 'A patient otherwise ready for extubation who is at high risk for postextubation laryngeal edema/stridor',[
 ('Every low-risk patient as an inflexible daily prerequisite','Routine universal testing can unnecessarily delay extubation because of false positives.'),('Only a patient who cannot yet initiate spontaneous breaths','That is not the intended extubation-readiness setting.'),('Any patient as a direct test of diaphragm strength','Cuff leak assesses upper-airway space, not muscle strength.')],
 'Use the test for its actual target','**Cuff-leak assessment estimates risk of postextubation upper-airway obstruction.**',['Risk factors and airway history guide selection.','An absent leak is not a perfect diagnosis of severe edema.'], '**Integrate the result into a safe extubation plan.**',['Do not treat it as a substitute for an SBT or secretion assessment.','Use preventive treatment when indicated.'],[['Target','Laryngeal edema/stridor risk'],['High-risk patient','Appropriate testing context'],['Limitation','False-positive/negative results occur']],[LI])

q('A patient is otherwise ready for extubation but fails a cuff-leak test and is at high stridor risk. Which approach is recommended by ATS/CHEST?', 'Give systemic glucocorticoids for at least 4 hours before extubation, with an appropriate airway plan',[
 ('Extubate without any consideration of upper-airway risk','The finding merits a preventive and rescue plan.'),('Delay extubation indefinitely until every leak value is normal','An absent leak is imperfect and indefinite delay adds harms.'),('Give a single steroid dose only after severe stridor has already caused collapse','Preventive timing is the relevant recommendation.')],
 'Use an actionable test result rather than only delay','**Pre-extubation glucocorticoids can reduce stridor-related failure in selected failed-leak patients.**',['The recommended lead time is at least four hours.','This does not eliminate the need for observation and reintubation readiness.'], '**Reassess airway history and other readiness factors.**',['An airway expert may be needed in a difficult reintubation scenario.','Do not allow a reassuring SBT to obscure upper-airway risk.'],[['Failed leak/high risk','Consider prophylactic steroid'],['Timing','At least 4 h beforehand'],['After extubation','Observe and have rescue capability']],[LI],style='clinical_scenario')

q('An older COPD patient with cardiac disease passes an SBT after several days of ventilation and has high extubation-failure risk. Which preventive strategy is often favored when suitable?', 'Planned extubation to noninvasive ventilation',[
 ('No planned respiratory support regardless of risk','High-risk patients can benefit from preventive noninvasive support.'),('Waiting for severe established failure before first considering NIV','Prevention is distinct from late rescue.'),('Mandatory tracheostomy despite otherwise adequate readiness','High risk alone does not make tracheostomy universally necessary.')],
 'Use preventive support in the right risk group','**NIV is favored for many patients at high risk of postextubation failure.**',['The decision depends on hypercapnia, cardiopulmonary disease, secretion management and contraindications.','HFNC can have a role when NIV is unsuitable or in other risk categories.'], '**Apply the plan immediately after extubation when indicated.**',['Monitor tolerance, gas exchange and effort.','Do not let NIV delay reintubation if failure develops.'],[['High-risk extubation','Consider planned NIV'],['Low risk','Different support options'],['Deterioration','Prompt escalation assessment']],[NS,ref('ATS/CHEST preventive NIV liberation guideline','https://journal.chestnet.org/article/S0012-3692%2816%2962324-3/fulltext')],style='clinical_scenario')

q('After extubation, a patient develops worsening hypoxemia, exhaustion and reduced consciousness despite noninvasive support. What is the priority?', 'Prompt assessment for reintubation rather than prolonging a failing noninvasive trial',[
 ('Continue NIV indefinitely because it avoids a tube','Avoiding a tube is not a benefit when needed support is delayed.'),('Use a normal earlier SBT to exclude current respiratory failure','The patient’s condition has changed.'),('Increase sedation until visible distress disappears without airway reassessment','This can obscure failure and worsen airway protection.')],
 'Prevention and rescue have different evidence and safety limits','**A failing postextubation patient needs timely airway and ventilation assessment.**',['Selected disease-specific contexts differ, but worsening consciousness and exhaustion are major warning signs.','NIV can mask deterioration if monitoring and escalation are inadequate.'], '**Treat the cause and secure support.**',['Assess edema, secretions, aspiration, airway obstruction and cardiopulmonary failure.','Do not repeat a prolonged unsuccessful strategy while organ injury accumulates.'],[['Preventive NIV','Applied before failure in a risk group'],['Established severe failure','May need reintubation'],['Monitoring','Must include effort and mental status']],[NI,NS],style='clinical_scenario')

q('A cooperative COPD exacerbation patient has pH 7.28, PaCO2 72 mmHg and persistent respiratory distress despite initial therapy. There is no immediate airway contraindication. Which support is standard?', 'Bilevel noninvasive ventilation with close reassessment',[
 ('Conventional oxygen alone regardless of persistent ventilatory failure','This does not adequately support the respiratory acidosis.'),('CPAP as an equivalent substitute for inspiratory ventilatory assistance in every hypercapnic patient','Bilevel support provides the relevant inspiratory assistance.'),('An unmonitored HFNC trial with no escalation plan','Acidotic hypercapnic failure needs appropriate ventilatory support and surveillance.')],
 'Treat ventilatory pump failure as well as hypoxemia','**NIV reduces intubation and mortality in appropriate acidotic COPD exacerbations.**',['Provide bronchodilators and other disease treatment concurrently.','More severe acidemia increases failure risk and requires ready access to intubation.'], '**Reassess pH, rate, effort and mental status early.**',['Do not continue a failing trial without escalation.','Controlled oxygen targets and the patient’s baseline context still matter.'],[['Bilevel NIV','Ventilatory assistance'],['COPD acidosis','Established indication'],['Nonresponse','Escalation assessment']],[NI,NS],style='clinical_scenario')

q('Which finding most strongly argues against continuing routine mask NIV without securing the airway?', 'Ongoing vomiting with inability to protect the airway',[
 ('A cooperative patient with an improving pH','This supports a successful trial rather than failure.'),('A mask leak corrected by refitting','A correctable interface issue does not alone establish a contraindication.'),('Mild anxiety that resolves with explanation and coaching','This can often be managed without abandoning an otherwise successful trial.')],
 'A mask does not protect the airway','**Aspiration risk and impaired airway protection can make NIV unsafe.**',['Immediate arrest, major instability and unmanageable secretions are other important concerns.','The exact contraindication assessment is clinical rather than one score.'], '**Use a timely intubation plan when needed.**',['Address the underlying cause and support oxygenation during preparation.','Do not sedate away the signs of airway failure.'],[['Airway protection','Essential safety consideration'],['Vomiting','Aspiration concern'],['Correctable leak/anxiety','May be manageable']],[NI],style='clinical_scenario')

q('What is a key safety requirement when using HFNC for de novo acute hypoxemic respiratory failure?', 'Close monitoring for excessive effort and treatment failure with timely escalation when needed',[
 ('Assume high oxygen saturation excludes injurious respiratory effort','Oxygenation can improve while work of breathing remains excessive.'),('Use the device to avoid intubation indefinitely regardless of trajectory','Delayed necessary intubation can be harmful.'),('Assume HFNC provides the same controlled ventilation as an invasive ventilator','It does not guarantee tidal volume or alveolar ventilation.')],
 'Noninvasive oxygenation support is not a guarantee of respiratory stability','**HFNC is evidence-supported for suitable acute hypoxemic patients.**',['Flow, oxygenation, respiratory rate, effort and mental state should be followed.','An index can support but not replace bedside judgment.'], '**Define failure criteria and an escalation pathway.**',['Treat the underlying cause and watch for hemodynamic deterioration.','Do not delay airway support in exhaustion or impaired protection.'],[['HFNC','Oxygenation/flow support'],['Effort','Can remain dangerously high'],['Escalation','Plan before failure occurs']],[NS,ref('ERS HFNC clinical guideline','https://doi.org/10.1183/13993003.01574-2021')])

q('A ventilated adult needs sedation with light arousability and delirium reduction as high priorities. What does the 2025 focused PADIS update suggest when clinically suitable?', 'Dexmedetomidine over propofol for those priorities',[
 ('Deep benzodiazepine sedation for every patient','This does not align with the light-sedation/delirium priorities in the stated scenario.'),('No analgesia because sedation treats pain adequately','Sedation and analgesia are distinct needs.'),('Neuromuscular blockade as a substitute for sedation','Paralysis provides neither analgesia nor amnesia.')],
 'Choose sedation by the clinical target','**PADIS conditionally favors dexmedetomidine when light sedation and/or delirium reduction are highest priorities.**',['Bradycardia and hypotension affect suitability.','Propofol or other strategies can be appropriate for different targets and circumstances.'], '**Use an explicit sedation goal and regular reassessment.**',['Treat pain and reversible agitation causes.','Coordinate awakening and breathing assessment when safe.'],[['Light sedation','Arousal and communication'],['Dexmedetomidine','Conditional preference for stated priorities'],['Safety','Hemodynamics and patient-specific needs']],[ref('SCCM focused PADIS update: 2025','https://www.sccm.org/clinical-resources/guidelines/guidelines/focused-update-padis-guideline')],style='clinical_scenario')

if __name__=='__main__':finalize('Critical Care and Toxicology',2,'Mechanical Ventilation','critical-ventilation',rows,36)
